mapper.select:
/*AdmGroupUserRelDAO.selectAdmGroupUserRel 어드민그룹사용자관계 정보 조회 */ SELECT GROUP_ID /* 그룹아이디 */ , USER_ID /* 사용자아이디 */ , USE_YN /* 사용여부 */ , FRST_REGI_USER_ID /* 최초등록사용자아이디 */ , FRST_REGI_TMSP /* 최초등록타임스탬프 */ , LAST_CHNG_USER_ID /* 최종변경사용자아이디 */ , LAST_CHNG_TMSP /* 최종변경타임스탬프 */ FROM ADM_GROUP_USER_REL WHERE 1=1
AND GROUP_ID = #{groupId} /* 그룹아이디 */
AND USER_ID = #{userId} /* 사용자아이디 */

mapper.insert:
/*AdmGroupUserRelDAO.insertAdmGroupUserRelHst 어드민그룹사용자관계 이력 등록*/
INSERT INTO ADM_GROUP_USER_REL_HST
SELECT *
FROM ADM_GROUP_USER_REL
WHERE GROUP_ID = #{groupId} AND USER_ID = #{userId}

mapper.update:
	/*AdmGroupUserRelDAO.resetAdmGroupUserRel 사용자 그룹ROLE 초기화*/
    	UPDATE ADM_GROUP_USER_REL
		SET USE_YN = 'N'
		     , LAST_CHNG_USER_ID = #{lastChngUserId}
			 , LAST_CHNG_TMSP = CURRENT_TIMESTAMP()
		 WHERE USER_ID = #{userId}

mapper.insert:
/*AdmGroupUserRelDAO.mergeBulkAdmGroupUserRel 사용자 그룹ROLE 저장*/
INSERT INTO ADM_GROUP_USER_REL (
	GROUP_ID
	, USER_ID
	, USE_YN
	, FRST_REGI_USER_ID
	, FRST_REGI_TMSP
)
VALUES

	(
		#{item.groupId}
		, #{item.userId}
		, 'Y'
		, #{item.frstRegiUserId}
		, CURRENT_TIMESTAMP()
	)

ON DUPLICATE KEY UPDATE
		USE_YN = 'Y'
		, LAST_CHNG_USER_ID = #{item.lastChngUserId}
		, LAST_CHNG_TMSP = CURRENT_TIMESTAMP()
